{"code": "from hermes_tools import read_file

# 检查是否有配置文件
files_to_check = [
    '/root/.ssh/config',
    '/etc/hosts',
    '/opt/hermes/config.yaml',
    '/opt/hermes/.hermes/config.yaml',
    '~/.hermes/config.yaml'
]

for file_path in files_to_check:
    try:
        result = read_file(path=file_path, limit=100)
        if result.get('content'):
            print(f"=== {file_path} ===")
            print(result['content'][:500])
            print()
    except Exception as e:
        print(f"{file_path}: 未找到或无法读取")
"}
